import React, { useEffect, useState } from 'react';
import { listDashboards, deleteDashboard, publishDashboard, listMetabaseDashboards, deleteMetabaseDashboard, duplicateMetabaseDashboard } from '../services/api';

export default function DashboardList({ onOpen, onCreate }) {
  const [dashboards, setDashboards] = useState([]);
  const [metabaseDashboards, setMetabaseDashboards] = useState([]);
  const [loading, setLoading] = useState(true);
  const [publishing, setPublishing] = useState(null);
  const [message, setMessage] = useState(null);

  const load = () => {
    setLoading(true);
    Promise.all([
      listDashboards(),
      listMetabaseDashboards()
    ])
      .then(([configs, metabase]) => {
        setDashboards(configs);
        setMetabaseDashboards(metabase);
      })
      .finally(() => setLoading(false));
  };

  useEffect(load, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this dashboard config?')) return;
    await deleteDashboard(id);
    load();
  };

  const handlePublish = async (id) => {
    setPublishing(id);
    setMessage(null);
    try {
      const res = await publishDashboard(id);
      setMessage({ type: 'success', text: `Published! Metabase Dashboard ID: ${res.dashboardId}` });
      load();
    } catch (e) {
      setMessage({ type: 'error', text: e.response?.data?.error || e.message });
    } finally {
      setPublishing(null);
    }
  };

  const handleEditMetabase = (dashboard) => {
    const newConfig = {
      name: `${dashboard.name} (Copy)`,
      description: dashboard.description || '',
      config: { cards: [] }
    };
    onOpen && onOpen(newConfig);
  };

  const handleDeleteMetabase = async (id, name) => {
    if (!window.confirm(`Delete Metabase dashboard "${name}"?`)) return;
    try {
      await deleteMetabaseDashboard(id);
      setMessage({ type: 'success', text: `Deleted dashboard "${name}"` });
      load();
    } catch (e) {
      setMessage({ type: 'error', text: e.response?.data?.error || e.message });
    }
  };

  const handleDuplicateMetabase = async (id, name) => {
    try {
      setMessage(null);
      const res = await duplicateMetabaseDashboard(id);
      setMessage({ type: 'success', text: `Duplicated "${name}" as "${res.name}"` });
      load();
    } catch (e) {
      setMessage({ type: 'error', text: e.response?.data?.error || e.message });
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <h2 style={{ margin: 0 }}>Dashboard Configs</h2>
        <button style={styles.createBtn} onClick={onCreate}>+ New Dashboard</button>
      </div>

      <div style={{ marginBottom: 32 }}>
        <h3 style={{ marginBottom: 16, marginTop: 0 }}>Metabase Dashboards</h3>
        {loading ? (
          <p>Loading...</p>
        ) : metabaseDashboards.length > 0 ? (
          <div style={styles.dashboardGrid}>
            {metabaseDashboards.map(d => (
              <div key={d.id} style={styles.dashboardCard}>
                <h4 style={styles.cardTitle}>{d.name}</h4>
                {d.description && <p style={styles.cardDescription}>{d.description}</p>}
                <div style={styles.cardMeta}>
                  <span>ID: {d.id}</span>
                </div>
                <div style={styles.cardActions}>
                  <button style={styles.actionBtn} onClick={() => handleEditMetabase(d)}>Edit</button>
                  <button style={{ ...styles.actionBtn, background: '#1971c2' }} onClick={() => handleDuplicateMetabase(d.id, d.name)}>Duplicate</button>
                  <button style={{ ...styles.actionBtn, background: '#c92a2a' }} onClick={() => handleDeleteMetabase(d.id, d.name)}>Delete</button>
                  <a
                    href={d.cta_section ? d.cta_section.link_text : '#'}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={styles.viewBtn}
                  >
                    View
                  </a>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p style={{ color: '#adb5bd' }}>No Metabase dashboards found</p>
        )}
      </div>

      {message && (
        <div style={{ ...styles.alert, background: message.type === 'success' ? '#d3f9d8' : '#ffe3e3', color: message.type === 'success' ? '#2f9e44' : '#c92a2a' }}>
          {message.text}
        </div>
      )}

      {loading ? <p>Loading...</p> : (
        <table style={styles.table}>
          <thead>
            <tr>{['Name', 'Status', 'Metabase ID', 'Updated', 'Actions'].map(h => <th key={h} style={styles.th}>{h}</th>)}</tr>
          </thead>
          <tbody>
            {dashboards.map(d => (
              <tr key={d.id} style={styles.tr}>
                <td style={styles.td}>{d.name}</td>
                <td style={styles.td}><span style={{ ...styles.badge, background: d.status === 'published' ? '#d3f9d8' : '#fff3bf' }}>{d.status}</span></td>
                <td style={styles.td}>{d.metabase_dashboard_id || '—'}</td>
                <td style={styles.td}>{new Date(d.updated_at).toLocaleString()}</td>
                <td style={styles.td}>
                  <button style={styles.actionBtn} onClick={() => onOpen(d)}>Edit</button>
                  <button style={{ ...styles.actionBtn, background: '#2f9e44', color: '#fff' }}
                    onClick={() => handlePublish(d.id)} disabled={publishing === d.id}>
                    {publishing === d.id ? 'Publishing…' : 'Publish'}
                  </button>
                  <button style={{ ...styles.actionBtn, background: '#c92a2a', color: '#fff' }}
                    onClick={() => handleDelete(d.id)}>Delete</button>
                </td>
              </tr>
            ))}
            {dashboards.length === 0 && (
              <tr><td colSpan={5} style={{ ...styles.td, textAlign: 'center', color: '#adb5bd' }}>No dashboards yet</td></tr>
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}

const styles = {
  page: { padding: 32, maxWidth: 1000, margin: '0 auto' },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 },
  createBtn: { padding: '10px 20px', background: '#4c6ef5', color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: 14 },
  alert: { padding: '10px 16px', borderRadius: 8, marginBottom: 16, fontSize: 13 },
  table: { width: '100%', borderCollapse: 'collapse' },
  th: { textAlign: 'left', padding: '10px 12px', background: '#f8f9fa', borderBottom: '2px solid #dee2e6', fontSize: 12, fontWeight: 700, color: '#495057' },
  tr: { borderBottom: '1px solid #f1f3f5' },
  td: { padding: '10px 12px', fontSize: 13 },
  badge: { padding: '2px 8px', borderRadius: 12, fontSize: 11, fontWeight: 600 },
  actionBtn: { padding: '4px 10px', marginRight: 6, border: 'none', borderRadius: 5, cursor: 'pointer', fontSize: 12, background: '#e9ecef' },
  dashboardGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 16 },
  dashboardCard: { border: '1px solid #dee2e6', borderRadius: 8, padding: 16, background: '#fff', display: 'flex', flexDirection: 'column' },
  cardTitle: { margin: '0 0 8px 0', fontSize: 16, fontWeight: 600, color: '#212529' },
  cardDescription: { margin: '0 0 12px 0', fontSize: 13, color: '#6c757d' },
  cardMeta: { fontSize: 12, color: '#adb5bd', marginBottom: 12 },
  cardActions: { display: 'flex', gap: 6, flexWrap: 'wrap', marginTop: 'auto' },
  viewBtn: { display: 'inline-block', padding: '6px 10px', background: '#4c6ef5', color: '#fff', borderRadius: 5, textDecoration: 'none', fontSize: 12, fontWeight: 600, border: 'none', cursor: 'pointer' },
};
